#!/usr/bin/env bash
# code-security-reviewer DG4 round-7 diff scan (adapted from round 6: source dab4562, freeze ea5e262; D13-D15 now the round-6 repair diff 1e0dc5d..dab4562), run in the disposable clone $TMPDIR/probe2 (git and grep only).
# NOTE: the candidate holds migrations 0028-0061 (0061_p4_finance_validation_correction_step.sql came with T-DG4-KBE-R5, F-DG4-101); the assignment text says 0028-0060, so D16/D17 cover 0028-0061.
cd $TMPDIR/probe2 || exit 2
B=d3e6fe6; C=dab4562
echo "== D0 freeze commit vs source commit (delivery metadata only expected)"; git diff --stat $C ea5e262 | tail -8
echo "== D1 P4 diff size (apps, packages)"; git diff --shortstat $B..$C -- apps packages
echo "== D2 migrations added/modified/deleted in P4 (only A expected; 0001-0027 untouched)"; git diff --name-status $B..$C -- packages/db/migrations | awk '{print $1}' | sort | uniq -c; git diff --name-status $B..$C -- packages/db/migrations | grep -v '^A' || echo "(none modified or deleted)"
echo "== D3 migration numbering contiguous"; ls packages/db/migrations | awk -F_ '{n=$1+0; if(n!=p+1) print "GAP at",$1; p=n} END{print "0001..00"p" contiguous check done"}'
echo "== D4 secret-like strings added in P4 (product, migrations, configs)"; git diff $B..$C -- apps packages docker* deploy* .env* 2>/dev/null | grep '^+' | grep -iE '(password|secret|api[_-]?key|private[_-]?key|BEGIN [A-Z ]*PRIVATE|token)\s*[:=]\s*["'"'"'][^"'"'"' ]{8,}' | grep -viE 'csrf|placeholder|example|synthetic|test|fixture|\$\{' | head -20 || true; echo "(end D4)"
echo "== D5 public CDN / remote URLs added in P4 product code"; git diff $B..$C -- apps packages | grep '^+' | grep -oE 'https?://[a-zA-Z0-9.-]+' | sort | uniq -c | sort -rn | head -20
echo "== D6 dynamic code in P4 product code (eval, new Function, Function(, vm., child_process)"; git diff $B..$C -- apps packages | grep '^+' | grep -v '^+++' | grep -E '\beval\(|new Function\(|[^a-zA-Z]Function\(|\bvm\.|child_process' | grep -vE '^\+\s*(//|\*)' | head -20; echo "(end D6)"
echo "== D7 raw SQL interpolation risk: sql.raw / sql.lit / sql.id with non-literal args in P4 product code"; git diff $B..$C -- apps packages | grep '^+' | grep -v '^+++' | grep -E 'sql\.(raw|lit)\(' | head -20; echo "(end D7)"
echo "== D8 innerHTML / dangerouslySetInnerHTML in P4 web code"; git diff $B..$C -- apps/web | grep '^+' | grep -E 'dangerouslySetInnerHTML|innerHTML' | head; echo "(end D8)"
echo "== D9 float arithmetic on money in P4 server code (parseFloat / Number(...amount|value|share|rate))"; git diff $B..$C -- apps/api/src apps/worker/src packages | grep '^+' | grep -v '^+++' | grep -E 'parseFloat\(|Number\([^)]*(amount|value|share|rate|ratio|percent)' | grep -v test | head; echo "(end D9)"
echo "== D10 p4-pending lists (all must be empty)"; for f in apps/api/test/support/p4-pending-*.ts; do n=$(node -e "const s=require('fs').readFileSync('$f','utf8');const m=s.match(/=\s*\[([\s\S]*?)\];/);console.log(m?(m[1].match(/\"[A-Za-z0-9]+\"/g)||[]).length:'composite')"); echo "$f $n"; done
echo "== D11 OpenAPI operation count"; node -e "const y=require('yaml');const d=y.parse(require('fs').readFileSync('docs/api/openapi.yaml','utf8'));let n=0;for(const p of Object.values(d.paths))for(const m of Object.keys(p))if(['get','post','put','patch','delete'].includes(m))n++;console.log('operations',n)" 2>/dev/null || (cd apps/api && node -e "const y=require('yaml');const d=y.parse(require('fs').readFileSync('../../docs/api/openapi.yaml','utf8'));let n=0;for(const p of Object.values(d.paths))for(const m of Object.keys(p))if(['get','post','put','patch','delete'].includes(m))n++;console.log('operations',n)")
echo "== D12 sql.raw / sql.lit anywhere in apps/*/src (full tree)"; grep -rn "sql\.raw(\|sql\.lit(" apps/api/src apps/worker/src packages/*/src --include=*.ts | grep -v test | head
echo "== D13 repair diff 1e0dc5d..dab4562: migrations (none expected)"; git diff --name-status 1e0dc5d..$C -- packages/db/migrations
echo "== D14 repair diff: files by area"; git diff --name-only 1e0dc5d..$C | awk -F/ '{print $1"/"$2}' | sort | uniq -c
echo "== D15 repair diff: unsafe sinks / float / remote URLs / sql.raw added (expect none in product code)"; git diff 1e0dc5d..$C -- apps packages | grep '^+' | grep -v '^+++' | grep -E 'dangerouslySetInnerHTML|innerHTML|\beval\(|new Function\(|sql\.(raw|lit)\(|parseFloat\(|https?://[a-z]' | grep -vE '^\+\s*(//|\*|--)' | head; echo "(end D15)"
echo "== D16 migrations 0028-0061: every CREATE TABLE has an append-only or guard attachment or is listed"; for f in packages/db/migrations/00{28..61}_*.sql; do t=$(grep -cE '^CREATE TABLE' $f); g=$(grep -cE 'p2_attach_guards|p2_attach_append_only|p4_attach|_guard\(\)|append_only' $f); echo "  $(basename $f) tables=$t guard-refs=$g"; done
echo "== D17 DELETE/TRUNCATE grants to mth_app in 0028-0061"; grep -nE 'GRANT[^;]*(DELETE|TRUNCATE)[^;]*mth_app' packages/db/migrations/00{28..61}_*.sql | head -20; echo "(end D17)"
